/** The prompt an agent sends to its image tool. bg: the shot's background (dark / light), so lighting matches. */
export function heroPrompt({ subject, app, promise, accent, dark = false, style = '3d' }) {
  const look = style === 'photo'
    ? 'Photorealistic product photograph, sharp focus, soft studio lighting'
    : 'Glossy 3D render, soft rounded shapes, gentle studio lighting, subtle reflections';
  return [
    `${look} of ${subject}, a single centred object, large in frame with a little space around it.`,
    accent ? `Colour palette built around ${accent}${dark ? ', lit to glow against a dark background' : ''}.` : '',
    `Mood: ${promise ? `"${promise}"` : `the app ${app || ''}`.trim()} — friendly, premium, App Store key art.`,
    'Transparent background (or a plain pure white background if transparency is not available). No shadow on the ground.',
    'No text, no letters, no numbers, no logos, no brand names, no UI, no phone, no people.',
    'Square, at least 1024 × 1024.',
  ].filter(Boolean).join('\n');
}

/** The first billboard shot of a plan, or null. */
export const billboardShot = (plan) => (plan?.shots || []).find((s) => (s.layout || 'hero-device') === 'billboard') || null;
